export const CATEGORY_NAMES={hat:'Mũ',glasses:'Kính',weapon:'Vũ khí',wings:'Cánh'};
export const PART_NAMES={head:'Đầu',torso:'Thân',armF:'Tay gần',armB:'Tay xa',legF:'Chân gần',legB:'Chân xa',body:'Thân',tail:'Đuôi',cape:'Áo choàng',skirt:'Vạt áo'};
export function outfitName(id){return OUTFIT_NAMES[id]||'Trang phục tự tạo'}
export function petName(id,fallback='Thú cưng tự tạo'){return PET_NAMES[id]||fallback}
export function translatedAccessoryName(entry){
 const id=typeof entry==='string'?entry:entry.id;
 if(id.startsWith('glasses_'))return GLASSES[id.slice(8)];
 if(WEAPONS[id])return WEAPONS[id];
 const weapon=id.match(/^(gs|sw|dg|kt|ds)_(.+)$/);if(weapon&&TRAITS[weapon[2]])return {gs:'Đại kiếm',sw:'Kiếm',dg:'Dao găm',kt:'Song trảo',ds:'Song kiếm'}[weapon[1]]+' '+TRAITS[weapon[2]];
 if(id.startsWith('hat_')){
  let suffix=id.slice(4),variant='';
  const ending=suffix.match(/_(open|awake|icon|w[123])$/);if(ending){variant={open:' · mở mặt',awake:' · thức tỉnh',icon:' · biểu tượng',w1:' · kiểu 1',w2:' · kiểu 2',w3:' · kiểu 3'}[ending[1]];suffix=suffix.slice(0,-ending[0].length)}
  if(HATS[suffix])return HATS[suffix]+variant;
  if(OUTFIT_NAMES[suffix])return 'Mũ '+OUTFIT_NAMES[suffix].toLocaleLowerCase('vi')+variant;
  if(suffix.startsWith('hc_')&&COLLECTION[suffix.slice(3)])return COLLECTION[suffix.slice(3)]+variant;
  if(suffix.startsWith('c3_')&&CLASS3[suffix.slice(3)])return 'Mũ '+CLASS3[suffix.slice(3)].toLocaleLowerCase('vi')+variant;
  const pirate=suffix.match(/^harlock([1-5])$/);if(pirate)return 'Mũ hải tặc · kiểu '+pirate[1];
 }
 return null;
}
export function accessoryName(entry){return translatedAccessoryName(entry)||(CATEGORY_NAMES[entry.category]||'Phụ kiện')+' tự tạo'}
const technicalName=name=>!name||/[\u0E00-\u0E7F]/.test(name)||/\.(png|webp|jpe?g)$/i.test(name)||/^(hat_|glasses_|w_|rig_|pr_|sw_|gs_|dg_|kt_|ds_)/.test(name);
export function attachmentName(a,catalog=[],index=0){
 const entry=catalog.find(e=>e.id===a.sourceId);
 if(entry){const legacyDefault=a.name===entry.name||a.name===entry.originalName||a.name===entry.id||technicalName(a.name);return legacyDefault?accessoryName(entry):a.name}
 if(!technicalName(a.name))return a.name;
 const category=a.category||{head:'hat',face:'glasses',handF:'weapon',handB:'weapon',back:'wings'}[a.socket];
 return (CATEGORY_NAMES[category]||'Phụ kiện')+' tải lên '+(index+1);
}
export function spriteName(id){const m=id.match(/^rig_(.+)_(head|torso|armF|armB|legF|legB|body|cape|skirt)(?:_v(\d+))?$/);return m?outfitName(m[1])+' · '+PART_NAMES[m[2]]+(m[3]?' · kiểu '+m[3]:''):null}
export function searchNames(query,...values){const clean=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase();return values.some(v=>clean(v).includes(clean(query)))}
